import hashlib,json,pathlib,re,subprocess,sys
r=json.loads(pathlib.Path(sys.argv[1]).read_bytes());root=pathlib.Path.cwd()
def h(b):return hashlib.sha256(b).hexdigest()
checks=0
for p in r["base_absence"]:
 assert subprocess.check_output(["git","ls-tree","--name-only",p["base_commit"],"--",p["path"]])==b"";checks+=1
for p in r["whole_provider_pins"]:
 b=subprocess.check_output(["git","show",p["commit"]+":"+p["path"]]);assert len(b)==p["git_bytes"] and h(b)==p["git_sha256"];checks+=1
for p in r["provider_regions"]:
 b=subprocess.check_output(["git","show",p["commit"]+":"+p["path"]]);q=b"".join(b.splitlines(keepends=True)[p["first_line"]-1:p["last_line"]]);assert len(q)==p["bytes"] and h(q)==p["sha256"];checks+=1
for p in r["new_source_pins"]:
 b=(root/p["path"]).read_bytes();assert len(b)==p["bytes"] and h(b)==p["sha256"] and b==pathlib.Path(p["frozen_path"]).read_bytes();checks+=1
for p in r["corrected_reserve_provider"]["pins"]:
 b=subprocess.check_output(["git","show",p["commit"]+":"+p["path"]]);assert len(b)==p["bytes"] and h(b)==p["sha256"];checks+=1
a=subprocess.check_output(["git","show",r["base_commit"]+":src/native_gui_named_value_array_reserve_storage.cpp"]);b=subprocess.check_output(["git","show",r["corrected_reserve_provider"]["commit"]+":src/native_gui_named_value_array_reserve_storage.cpp"]);assert re.sub(rb"\boffset\b",b"byte_offset",a)==b and re.sub(rb"\bbyte_offset\b",b"offset",b)==a;checks+=1
p=r["design_proposal"];b=pathlib.Path(p["frozen_path"]).read_bytes();assert len(b)==p["bytes"] and h(b)==p["sha256"];checks+=1
pe=pathlib.Path(r["pe"]["path"]).read_bytes();assert h(pe)==r["pe"]["sha256"];checks+=1
for p in [r["native"]]+r["supporting_native_ranges"]:
 b=bytes.fromhex(p["hex"]);assert len(b)==p["bytes"] and h(b)==p["sha256"] and pe[p["pe_file_offset"]:p["pe_file_offset"]+len(b)]==b;checks+=1
n=r["native"];assert bytes.fromhex(n["hex"])==b"".join(bytes.fromhex(o["bytes_hex"]) for o in n["instructions"]) and len(n["instructions"])==35
for p in n["exports"]:
 b=pathlib.Path(p["frozen_path"]).read_bytes();assert len(b)==p["bytes"] and h(b)==p["sha256"];checks+=1
s=(root/r["new_source_pins"][1]["path"]).read_text();positions=[s.index(x["needle"]) for x in r["source_order"]];assert positions==sorted(positions);checks+=1
d=(root/r["document_pin"]["path"]).read_bytes();assert len(d)==r["document_pin"]["bytes"] and h(d)==r["document_pin"]["sha256"];checks+=1
assert r["compiled"] is False and r["credit"]["native_origin"] is False
print(json.dumps({"pass":True,"checks":checks,"native_ops":35,"native_calls":2,"source_order_pins":len(r["source_order"]),"providers":len(r["whole_provider_pins"]),"regions":len(r["provider_regions"]),"correction_pins":2}))
